import re

PAGE = re.compile(r'^(?:https?://)?(?:www\.|m\.)?clips\.example/(watch\?|shorts/|live/)', re.I)
KIND = {'watch?': 'video', 'shorts/': 'short', 'live/': 'live'}
SHARED = {'Hy6uJ2sXe7q': 'video', 'Rf8tG4yNo5d': 'video', 'Ks3lI6fBt2y': 'video'}


def kind_of(url):
    m = PAGE.match(url.strip())
    if m:
        return KIND[m.group(1).lower()]
    clip = url.strip().split('clp.example/')[-1].split('?')[0]
    return SHARED.get(clip, 'unknown')

