"""Keeping the inventory between runs (R-2): one JSON file; every change holds a lock, because two tills write it (G-1)."""
import json
import os
import tempfile
import time

from shelf.model import Item


def _read(path):
    with open(path, encoding="utf-8") as f:
        return [Item(r["sku"], r["name"], r["qty"], r["reorder_at"]) for r in json.load(f)]


def _write(items, path):
    rows = [{"sku": i.sku, "name": i.name, "qty": i.qty, "reorder_at": i.reorder_at} for i in items]
    fd, tmp = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(path)))
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        json.dump(rows, f)
    for _ in range(200):          # Windows refuses to replace a file another process has open for a moment
        try:
            os.replace(tmp, path)
            return
        except PermissionError:
            time.sleep(0.01)
    os.replace(tmp, path)


def _locked(path, change):
    """Run change() while this process holds the inventory's lock file (created exclusively, removed after)."""
    lock = str(path) + ".lock"
    while True:
        try:
            fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            break
        except FileExistsError:
            time.sleep(0.002)
    try:
        return change()
    finally:
        os.close(fd)
        os.remove(lock)


def save(items, path):
    _locked(path, lambda: _write(items, path))


def load(path):
    return _locked(path, lambda: _read(path))


def sell(path, sku, n):
    def change():
        items = _read(path)
        for i in items:
            if i.sku == sku:
                i.qty -= n
        _write(items, path)
    _locked(path, change)

